{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Cilomilast has close to 100% absolute oral bioavailability in humans, demonstrating that a lipophilic small-molecule drug can be essentially completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Nevirapine absolute oral bioavailability is 91 ± 8% in healthy volunteers, supporting high F for a lipophilic, moderately soluble oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Thalidomide absolute oral bioavailability is probably high (80–100%) at low doses in fasting volunteers, supporting high F for a lipophilic neutral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethosuximide oral bioavailability is >90% in humans, supporting high F for a small, lipophilic, non-ionizable drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Rasagiline, a small lipophilic amine with first-pass metabolism, still has an absolute oral bioavailability of 36%, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pentazocine has a low oral bioavailability of 18%, but this is due to extensive first-pass metabolism of a phenolic opioid and is not transferable to the adamantane primary amine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Memantine is a lipophilic adamantane primary amine; multiple structurally and physicochemically similar small lipophilic drugs show high oral bioavailability (mostly >80%, all relevant analogs >20%), and the only low-F analog has a phenolic first-pass liability absent in memantine. Therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for memantine itself is present in the supplied evidence set.",
    "The transferable analogs differ in exact ionizability and metabolic pathways, so quantitative F for memantine is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

